#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int numFriendRequests(vector<int>& ages) {
        sort(ages.begin(), ages.end());
        int n = ages.size(), res = 0;
        for (int i = 0; i < n; ++i) {
            int age = ages[i];
            if (age < 15) continue;
            int low = lower_bound(ages.begin(), ages.end(), age / 2 + 7 + 1) - ages.begin();
            int high = upper_bound(ages.begin(), ages.end(), age) - ages.begin();
            res += high - low - 1;
        }
        return res;
    }
};
